#!/usr/bin/env bash
# tests/check-md-slug-data-sync.sh -- markdown-library-plan 6.3: the Unicode
# data the heading-id rules need (what NFKD leaves of each code point in ASCII,
# and the combining marks) exists twice, generated by tools/gen-md-slug-data.py: the file-scope C block of
# stdlib/markdown/slug-data.tur (the compiled back end) and src/turi/md_slug_data.inc
# (the interpreter's native).  They must be the same text, or the two back
# ends give a heading different ids.  This checks the two copies against each
# other, not against the generator, so it needs no Unicode data.
set -uo pipefail
cd "$(dirname "$0")/.."
if ! command -v python3 >/dev/null 2>&1; then
    echo "SKIP check-md-slug-data-sync: python3 not found"
    exit 0
fi
python3 - <<'PY'
import sys
tur = open("stdlib/markdown/slug-data.tur", encoding="ascii").read()
inc = open("src/turi/md_slug_data.inc", encoding="ascii").read()
start = tur.index("```c\n") + 5
end = tur.index("```\n", start)
if tur[start:end] != inc:
    print("FAIL check-md-slug-data-sync: stdlib/markdown/slug-data.tur's C block and "
          "src/turi/md_slug_data.inc differ -- regenerate both with "
          "python3 tools/gen-md-slug-data.py --ucd build/ucd")
    sys.exit(1)
print("PASS check-md-slug-data-sync (%d bytes of C, identical)" % len(inc))
PY
